import { test } from "node:test";
import assert from "node:assert/strict";
import { bookingHandlers } from "../src/bookings/handlers.ts";
import { ReservationService, type Reservation } from "../src/bookings/service.ts";
import { UpstreamTimeoutError } from "../src/bookings/errors.ts";

function setup(opts: { inventory?: () => Promise<void>; seed?: Reservation[] } = {}) {
    const rows = new Map<string, Reservation>((opts.seed ?? []).map((r) => [r.id, r]));
    const repo = {
        get: async (id: string) => rows.get(id) ?? null,
        forRoom: async (roomId: string) => [...rows.values()].filter((r) => r.roomId === roomId),
        save: async (r: Reservation) => void rows.set(r.id, r),
    };
    let n = 0;
    const logged: unknown[] = [];
    const service = new ReservationService(repo, { hold: opts.inventory ?? (async () => {}) }, () => `res_${++n}`);
    return { api: bookingHandlers(service, (e) => logged.push(e)), rows, logged };
}

const stay = { roomId: "101", guestName: "Grace Hopper", checkIn: "2026-12-01", checkOut: "2026-12-04" };
const errorOf = (body: unknown) => (body as { error: Record<string, string> }).error;

test("booking a free room answers 201 with a Location header", async () => {
    const { api } = setup();
    const res = await api.create({ params: {}, body: stay });
    assert.equal(res.status, 201);
    assert.equal(res.headers?.Location, "/reservations/res_1");
});

test("malformed input is a 400 that names the offending field", async () => {
    const { api } = setup();
    const res = await api.create({ params: {}, body: { ...stay, checkOut: "2026-11-30" } });
    assert.equal(res.status, 400);
    assert.deepEqual(errorOf(res.body), { code: "invalid_request", message: "checkOut must be after checkIn", field: "checkOut" });
});

test("a well-formed request that breaks a booking rule is a 422", async () => {
    const { api } = setup();
    const res = await api.create({ params: {}, body: { ...stay, checkOut: "2027-02-01" } });
    assert.equal(res.status, 422);
    assert.equal(errorOf(res.body).code, "stay_too_long");
});

test("looking up a reservation that doesn't exist is a 404", async () => {
    const { api } = setup();
    const res = await api.get({ params: { id: "res_404" } });
    console.log("GET /reservations/res_404 ->", res.status, res.body);
    assert.equal(res.status, 404);
    assert.equal(errorOf(res.body).code, "reservation_not_found");
});

test("booking nights that are already taken is a 409 conflict", async () => {
    const { api, rows } = setup();
    await api.create({ params: {}, body: stay });
    const res = await api.create({ params: {}, body: { ...stay, guestName: "Alan Turing", checkIn: "2026-12-03", checkOut: "2026-12-06" } });
    assert.equal(res.status, 409);
    assert.equal(errorOf(res.body).code, "room_unavailable");
    assert.equal(rows.size, 1);
});

test("cancelling after check-in is a 409 and leaves the stay in place", async () => {
    const { api, rows } = setup({ seed: [{ ...stay, id: "res_9", status: "checked_in" }] });
    const res = await api.cancel({ params: { id: "res_9" } });
    assert.equal(res.status, 409);
    assert.equal(errorOf(res.body).code, "reservation_closed");
    assert.equal(rows.get("res_9")?.status, "checked_in");
    assert.equal((await api.cancel({ params: { id: "res_nope" } })).status, 404);
});

test("upstream timeouts are a retryable 503 and unexpected bugs a generic 500", async () => {
    const slow = setup({ inventory: async () => { throw new UpstreamTimeoutError("channel-manager", 5); } });
    const timedOut = await slow.api.create({ params: {}, body: stay });
    assert.equal(timedOut.status, 503);
    assert.equal(timedOut.headers?.["Retry-After"], "5");

    const broken = setup({ inventory: async () => { throw new TypeError("cannot read properties of undefined (reading 'rate')"); } });
    const res = await broken.api.create({ params: {}, body: stay });
    assert.equal(res.status, 500);
    assert.deepEqual(errorOf(res.body), { code: "internal_error", message: "Something went wrong" });
    assert.equal(broken.logged.length, 1);
});
